\newcommand{\op}{\mathrm{op}}

\title{A Galois-Theoretic Bridge: Knaster--Tarski Fixed-Point Lattices and the Zariski Topology}
\author{Aristotle}
\date{June 23, 2026}

\begin{document}

\begin{abstract}
We develop, from first principles, the order-theoretic core that links Galois
connections to both fixed-point theory and algebraic geometry. We prove two main
results. \emph{Theorem A} is a Knaster--Tarski theorem tailored to Galois
connections: given a Galois connection $l \dashv u$ between complete lattices
$\alpha$ and $\beta$, the fixed points of the induced closure operator
$c = u \circ l$, namely $\Fix = \{x \in \alpha : u(l(x)) = x\}$, form a complete
lattice. The construction uses only the adjunction axioms: meets are inherited
from $\alpha$ (the infimum of closed elements is closed), joins are the closure
of the ambient join, and the complete-lattice structure is assembled from the
infimum via the standard order-theoretic builder. \emph{Theorem B} instantiates
the machine in commutative algebra: for a commutative ring $R$, the pair
$(\zloc, \vid)$ is an antitone Galois connection between the ideals of $R$ and
the subsets of the prime spectrum $\Spec R$; its closure operator is the radical
of an ideal; and its fixed points are exactly the radical ideals---the
Zariski-closed sets in algebraic disguise.
\end{abstract}

\maketitle

\section{Introduction}

A \emph{Galois connection} is the order-theoretic distillation of adjunction:
two order-preserving maps between posets that are universally compatible with the
order. The notion abstracts the classical correspondence between subgroups and
intermediate fields, but its reach is far broader: Galois connections govern
closure operators in topology, consequence operators in logic, abstract
interpretation in program analysis, formal concept analysis in data mining, and
the algebra--geometry dictionary at the foundation of algebraic geometry.

This paper isolates the precise sense in which Galois connections
\emph{manufacture} order-theoretic and topological structure. We answer two
questions:
\begin{enumerate}
  \item What is the structure of the fixed points of the closure operator induced
        by a Galois connection? (Answer: a complete lattice---Theorem~A.)
  \item How does the Zariski topology on a prime spectrum arise as an instance of
        this machinery? (Answer: as the fixed-point side of the
        $\zloc/\vid$ Galois connection, whose closure is the radical---Theorem~B.)
\end{enumerate}
Both results are formalized; below we state each with full mathematical content
and a faithful proof sketch.

\section{Preliminaries and definitions}

\subsection{Posets and complete lattices}
A \emph{partially ordered set} (poset) is a set with a reflexive, antisymmetric,
transitive relation $\le$. A \emph{complete lattice} is a poset in which every
subset $S$ has an infimum $\bigsqcap S$ and a supremum $\bigsqcup S$. The
existence of all infima already forces all suprema via
$\bigsqcup S = \bigsqcap \{ y : \forall x \in S,\ x \le y\}$; this underlies the
builder \texttt{completeLatticeOfInf}, which produces a complete-lattice
structure from a proof that a designated infimum operation always yields the
greatest lower bound.

\subsection{Galois connections}
\begin{definition}
Let $\alpha,\beta$ be posets and $l : \alpha \to \beta$, $u : \beta \to \alpha$.
The pair $(l,u)$ is a \emph{(monotone) Galois connection}, written $l \dashv u$,
if for all $a \in \alpha$, $b \in \beta$,
\begin{equation}
  l(a) \le b \iff a \le u(b). \tag{GC}
\end{equation}
\end{definition}
Standard consequences: both $l,u$ are monotone; $a \le u(l(a))$ and
$l(u(b)) \le b$; and $u(l(u(b))) = u(b)$, $l(u(l(a))) = l(a)$. An
\emph{antitone} Galois connection between $\alpha$ and $\beta$ is a monotone one
between $\alpha$ and $\beta^{\op}$.

\subsection{The induced closure operator}
Given $l \dashv u$, set $c := u \circ l$. Then $c$ is a \emph{closure operator}:
\begin{lemma}[\texttt{le\_closure}; extensive]
For all $a$, $a \le u(l(a))$.
\end{lemma}
\begin{lemma}[\texttt{closure\_idem}; idempotent]
For all $a$, $u(l(u(l(a)))) = u(l(a))$.
\end{lemma}
Together with monotonicity, $c$ is a closure operator. An element $x$ is
\emph{closed} (a \emph{fixed point}) if $u(l(x)) = x$. We write
\[
  \Fix(gc) := \{ x \in \alpha : u(l(x)) = x \},
\]
ordered as a subposet of $\alpha$.

\section{Theorem A: a Knaster--Tarski theorem for Galois connections}

\begin{theorem}[\texttt{instCompleteLattice}]\label{thmA}
Let $\alpha,\beta$ be complete lattices and $l \dashv u$ a Galois connection
between them. Then $\Fix(gc)$ is a complete lattice.
\end{theorem}

The proof uses only (GC), its order-theoretic consequences, and
\texttt{completeLatticeOfInf}.

\subsection{Meets}
\begin{lemma}[\texttt{closed\_sInf}]\label{lem:meet}
If $S \subseteq \alpha$ and $u(l(x)) = x$ for all $x \in S$, then
$u(l(\bigsqcap S)) = \bigsqcap S$.
\end{lemma}
\begin{proof}[Proof sketch]
By extensivity, $\bigsqcap S \le u(l(\bigsqcap S))$. Conversely, for each
$x \in S$, $\bigsqcap S \le x$ gives $u(l(\bigsqcap S)) \le u(l(x)) = x$ by
monotonicity and closedness; the greatest-lower-bound property yields
$u(l(\bigsqcap S)) \le \bigsqcap S$. Antisymmetry finishes.
\end{proof}
Hence $\Fix(gc)$ carries an infimum (\texttt{instInfSet}) given by the ambient
infimum of the underlying elements, with $\iota(\bigsqcap_{\Fix} S) =
\bigsqcap(\iota[S])$ (\texttt{coe\_sInf}).

\begin{lemma}[\texttt{isGLB\_sInf}]\label{lem:glb}
For every $S \subseteq \Fix(gc)$, $\bigsqcap_{\Fix} S$ is the greatest lower
bound of $S$ in $\Fix(gc)$.
\end{lemma}
\begin{proof}[Proof sketch]
Lower bound: each member of $S$ dominates the ambient infimum. Greatest: any
closed lower bound $t$ satisfies $\iota(t) \le \iota(x)$ for all $x \in S$,
hence $\iota(t) \le \bigsqcap(\iota[S])$.
\end{proof}

\subsection{Assembly}
Applying \texttt{completeLatticeOfInf} to Lemma~\ref{lem:glb} yields a
\texttt{CompleteLattice} structure on $\Fix(gc)$, proving Theorem~\ref{thmA}. No
external fixed-point theorem is used.

\subsection{The join is the re-closed ambient join}
\begin{proposition}[\texttt{coe\_sSup}]\label{prop:join}
For $S \subseteq \Fix(gc)$,
\[
  \iota\!\left(\textstyle\bigsqcup_{\Fix} S\right)
  = u\!\left(l\left(\textstyle\bigsqcup(\iota[S])\right)\right).
\]
\end{proposition}
\begin{proof}[Proof sketch]
Let $w := u(l(\bigsqcup(\iota[S])))$, closed by idempotence. For $x\in S$,
$\iota(x)\le\bigsqcup(\iota[S])\le w$, so $w$ is an upper bound. If
$\langle t\rangle$ is a closed upper bound then $\bigsqcup(\iota[S])\le t$,
whence $w \le u(l(t)) = t$. Thus $w$ is the least upper bound.
\end{proof}

\begin{lemma}[\texttt{closure\_le\_iff}]\label{lem:ump}
For closed $x \in \Fix(gc)$ and any $a \in \alpha$,
$\; u(l(a)) \le \iota(x) \iff a \le \iota(x).$
\end{lemma}
\begin{proof}[Proof sketch]
$(\Rightarrow)$ $a \le u(l(a)) \le \iota(x)$. $(\Leftarrow)$
$u(l(a)) \le u(l(\iota(x))) = \iota(x)$ by monotonicity and closedness.
\end{proof}
Lemma~\ref{lem:ump} says $c(a)$ is the least closed element above $a$; $\Fix(gc)$
is a reflective subposet of $\alpha$.

\section{Theorem B: the Zariski topology from a Galois connection}

Fix a commutative ring $R$.

\subsection{Objects}
$\Ideal R$ is the complete lattice of ideals; $\Spec R$ is the set of prime
ideals, each $p$ with underlying ideal $p.\mathrm{asIdeal}$. For an ideal $I$,
$\zloc(I) = \{ p \in \Spec R : I \subseteq p\}$; for $S \subseteq \Spec R$,
$\vid(S) = \bigcap_{p\in S} p.\mathrm{asIdeal}$.

\begin{lemma}[\texttt{vanishingIdeal\_eq\_iInf}]
For $S \subseteq \Spec R$, $\ \vid(S) = \bigsqcap_{p\in S} p.\mathrm{asIdeal}.$
\end{lemma}

\subsection{The adjunction}
\begin{theorem}[\texttt{zariski\_adjunction}, \texttt{zariski\_galoisConnection}]\label{thmB}
For every ideal $I$ and every $S \subseteq \Spec R$,
\[
  I \le \vid(S) \iff S \subseteq \zloc(I).
\]
Equivalently, $(\zloc,\vid)$ is a Galois connection between $\Ideal R$ and
$(\mathrm{Set}(\Spec R))^{\op}$.
\end{theorem}
\begin{proof}[Proof sketch]
Both sides assert $I \subseteq p$ for all $p \in S$. The order on the spectrum
side is reversed (hence $(\cdot)^{\op}$), reflecting that $\zloc$ is antitone:
larger ideals cut out smaller loci.
\end{proof}
Since $\Ideal R$ and $(\mathrm{Set}(\Spec R))^{\op}$ are complete lattices,
Theorem~\ref{thmA} applies: the fixed points form a complete lattice.

\subsection{Closure is the radical}
\begin{theorem}[\texttt{zariski\_closure\_eq\_radical}]\label{thmBrad}
For every ideal $I$, $\ \vid(\zloc(I)) = \sqrt{I},$ where
$\sqrt{I} = \{ r : \exists n,\ r^n \in I\}$.
\end{theorem}
\begin{proof}[Proof sketch]
$\vid(\zloc(I))$ is the intersection of all primes containing $I$, which equals
$\sqrt{I}$ by Krull's characterization of the radical.
\end{proof}

\begin{corollary}[\texttt{zariski\_fixedPoint\_iff\_radical}]\label{corB}
For every ideal $I$, $\ \vid(\zloc(I)) = I \iff I$ is radical.
\end{corollary}
\begin{proof}[Proof sketch]
By Theorem~\ref{thmBrad}, the left side is $\sqrt I = I$, equivalent to $I$ being
radical.
\end{proof}

\subsection{Synthesis}
Combining Theorems~\ref{thmA} and~\ref{thmB}: the radical ideals of $R$ form a
complete lattice, anti-isomorphic via the adjunction to the lattice of
Zariski-closed subsets of $\Spec R$. Meets of radical ideals are intersections
(Lemma~\ref{lem:meet}); joins are re-closed: the join of $I,J$ is $\sqrt{I+J}$
(Proposition~\ref{prop:join}).

\section{Applications}
\begin{itemize}
  \item \textbf{Algebraic geometry:} Theorem~B is the structural foundation of the
        ideal--variety dictionary.
  \item \textbf{Abstract interpretation:} the round-trip closure is the best sound
        approximation; Theorem~A gives the complete lattice of abstract properties.
  \item \textbf{Formal concept analysis:} $(\mathrm{extent},\mathrm{intent})$ is a
        Galois connection whose fixed points form the concept lattice (Theorem~A).
  \item \textbf{Logic:} consequence operators are closures; fixed points are
        deductively closed theories.
\end{itemize}

\section{Discussion and future directions}
A single minimal hypothesis (a Galois connection between complete lattices)
yields both a robust structural conclusion (a complete lattice of fixed points)
and, upon instantiation, the Zariski topology via the radical. The
``re-closed join'' phenomenon (Proposition~\ref{prop:join}) uniformly explains
why unions of varieties are varieties while sums of radical ideals must be
re-radicalized. Future directions include: bicontinuity/openness of adjoints in
Alexandrov topologies; a characterization of when the fixed-point lattice is a
frame (iff the closure is a nucleus); uniqueness of the Zariski topology as the
topology whose closure equals the Galois closure; and a complete-lattice
anti-isomorphism between radical ideals and Zariski-closed sets.

\section{Conclusion}
We formalized a Knaster--Tarski theorem for Galois connections (Theorem~A) and
showed it specializes to the Zariski topology (Theorem~B), bridging order
theory, topology, and commutative algebra through the single lens of adjunction.

\end{document}

