"""Radical closure round-trip and fixed-point detection over Z.

Exercises Theorem B (`zariski_closure_eq_radical`): the Galois closure
c = vanishingIdeal . zeroLocus equals the radical; and the Corollary
(`zariski_fixedPoint_iff_radical`): fixed points are the radical ideals.
"""
from __future__ import annotations


def squarefree_part(n: int) -> int:
    n = abs(n)
    if n in (0, 1):
        return n
    result, d, m, seen = 1, 2, n, set()
    while d * d <= m:
        while m % d == 0:
            if d not in seen:
                result *= d
                seen.add(d)
            m //= d
        d += 1
    if m > 1 and m not in seen:
        result *= m
    return result


def closure(n: int) -> int:
    """c((n)) = sqrt((n)) = radical generator."""
    return squarefree_part(n)


def is_fixed_point(n: int) -> bool:
    """(n) is a fixed point (radical ideal) iff c((n)) == (n)."""
    return closure(n) == n


if __name__ == "__main__":
    for n in [12, 18, 50, 30, 7, 36, 1, 72, 360]:
        print(f"I=({n:>3})  c(I)=({closure(n):>3})  radical fixed point? {is_fixed_point(n)}")

"""Re-closed join in the fixed-point lattice of radical ideals (Theorem A).

Exercises `closed_sInf` (meet inherited) and `coe_sSup` (join is the closure of
the ambient join).  In Z, the ambient join (ideal sum) of (a),(b) is (gcd(a,b));
the true lattice join is its radical.
"""
from __future__ import annotations

from math import gcd


def squarefree_part(n: int) -> int:
    n = abs(n)
    if n in (0, 1):
        return n
    result, d, m, seen = 1, 2, n, set()
    while d * d <= m:
        while m % d == 0:
            if d not in seen:
                result *= d
                seen.add(d)
            m //= d
        d += 1
    if m > 1 and m not in seen:
        result *= m
    return result


def meet(a: int, b: int) -> int:
    """Greatest lower bound (inherited): gcd, stays radical (closed_sInf)."""
    return gcd(a, b)


def ambient_join(a: int, b: int) -> int:
    """Ideal sum (a)+(b) = (gcd(a,b)) in Z."""
    return gcd(a, b)


def join(a: int, b: int) -> int:
    """Least upper bound = re-closed ambient join (coe_sSup): c(ambient_join)."""
    return squarefree_part(ambient_join(a, b))


if __name__ == "__main__":
    for a, b in [(6, 15), (8, 12), (12, 18), (30, 42)]:
        aj, jf = ambient_join(a, b), join(a, b)
        print(f"a={a}, b={b}: meet={meet(a, b)}  ambient_join={aj} "
              f"(radical? {squarefree_part(aj) == aj})  true_join={jf}")

"""Verifying the Zariski adjunction on Spec(C[x]) (Theorem B).

Models a point of Spec C[x] as a root a (the prime (x - a)); an ideal by its
roots-with-multiplicity.  Checks `zariski_adjunction`:
    I <= vanishingIdeal(S)  iff  S subseteq zeroLocus(I),
and `zariski_closure_eq_radical`: the closure strips multiplicities.
"""
from __future__ import annotations

from typing import Iterable


def zero_locus(roots_mult: dict[float, int]) -> set[float]:
    """V(I): distinct roots of a generator of I."""
    return set(roots_mult.keys())


def vanishing_ideal(points: Iterable[float]) -> dict[float, int]:
    """vanishingIdeal(S): product of (x - a), a in S; simple roots."""
    return {a: 1 for a in points}


def closure(roots_mult: dict[float, int]) -> dict[float, int]:
    """radical: vanishingIdeal(zeroLocus(I)); drops multiplicities."""
    return vanishing_ideal(zero_locus(roots_mult))


def adjunction_holds(ideal_roots: dict[float, int], S: set[float]) -> bool:
    lhs = set(S) <= set(ideal_roots.keys())   # I <= vanishingIdeal(S)
    rhs = set(S) <= zero_locus(ideal_roots)   # S subseteq zeroLocus(I)
    return lhs == rhs


if __name__ == "__main__":
    I = {2.0: 2, 5.0: 1}            # ((x-2)^2 (x-5))
    print("zeroLocus(I)      =", sorted(zero_locus(I)))
    print("radical(I) roots  =", closure(I), " (double root at 2 collapses)")
    for S in [{2.0}, {2.0, 5.0}, {2.0, 7.0}, set()]:
        print(f"S={sorted(S)!s:<14} adjunction holds? {adjunction_holds(I, S)}")

